    """Expand a partial diagonal periodic color pattern."""
    h, w = len(grid), len(grid[0])
    # Periodically extend the colored clues over anti-diagonals.
    # First gather known color sequences on each anti-diagonal index.
    groups = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                groups.setdefault(r + c, []).append(grid[r][c])

    # This general task is a diagonal wallpaper; derive the shortest period
    # compatible with the clue coloring where possible.
    known = {k: vals[0] for k, vals in groups.items()}
    period = None
    for p in range(1, h + w + 1):
        residues = {}
        ok = True
        for k, color in known.items():
            q = k % p
            if q in residues and residues[q] != color:
                ok = False
                break
            residues[q] = color
        if ok:
            period = p
            motif = residues
            break

    if period is None:
        # When clues collide, retain a local diagonal band approximation.
        period = 2
        motif = {0: 1, 1: 2}
    # Fill any unobserved residues by extending the nearest known motif entry.
    present = sorted(motif)
    for q in range(period):
        if q not in motif:
            motif[q] = motif[min(present, key=lambda x: min((q-x)%period,(x-q)%period))]
    return [[motif[(r+c) % period] for c in range(w)] for r in range(h)]

if __name__ == '__main__':
