    h, w = len(grid), len(grid[0])
    # The colored diagonal lines are samples from a periodic wallpaper whose
    # colors are constant on diagonals r+c. Recover the cycle by fitting the
    # smallest period to all observed bands, then paint each band.
    stripes = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                stripes[r + c] = grid[r][c]

    for period in range(1, h + w + 1):
        motif = {}
        valid = True
        for diagonal, color in stripes.items():
            residue = diagonal % period
            if residue in motif and motif[residue] != color:
                valid = False
                break
            motif[residue] = color
        if valid:
            break

    # Seed inputs may omit some stripes; colors recur cyclically through the
    # observed diagonal sequence. Fill omitted residues by repeating in order.
    known = sorted(motif.items())
    if len(motif) < period:
        base_colors = [color for _, color in known]
        for residue in range(period):
            if residue not in motif:
                motif[residue] = base_colors[residue % len(base_colors)]

    return [[motif[(r + c) % period] for c in range(w)] for r in range(h)]

